B.agL=new A.Pc("vx-cli",B.mh,"vx CLI Reference",null,null,"Zero-dependency Pure Python CLI for Linux, macOS, and Android (Termux).",B.cqB,B.cmk,"INSTALL VX CLI","curl -fsSL https://raw.githubusercontent.com/kcoaguila-dev/veraxi/main/install.sh | bash\nvx doctor",null,null)
B.cnP=s(["Veraxi parses CycloneDX and SPDX JSON SBOMs alongside `pyproject.toml`, `uv.lock`, `package.json`, and `pubspec.yaml` with fail-closed version matching sorted by matched -> KEV -> EPSS.","Ingest Semgrep, Opengrep, Trivy, or CodeQL SARIF 2.1.0 `codeFlows` taint paths and Nuclei recon findings into Neo4j (`:SecurityFinding`) and Qdrant, cross-referenced against your indexed code graph."],t.s)
B.agP=new A.Pc("appsec-rules",B.mh,"AppSec, SBOMs & Rules",null,null,"Local, NDA-safe vulnerability triage combining NVD 2.0, OSV.dev, CISA KEV, EPSS, and code reachability.",B.cnP,B.y6,"SYNC FEEDS & RUN REACHABILITY REPORT","vx vuln sync\nvx vuln attack-sync\nvx vuln report . --sbom sbom.cdx.json --reachability",null,null)
